        /// <summary>
        /// Resets the winning email notification.
        /// </summary>
        /// <param name="model">The model.</param>
        /// <param name="result">The result.</param>
        /// <returns>
        /// Email will be send success or not.
        /// </returns>
        public static bool ResetWinningEmailNotification(GetResetWinningCriteria criteria, ResetStatus status)
        {
            bool isSuccess = true;
            ResetWinningMailCollection mailCollection = ResetWinningMailSection.Instance.ErrorInformEmail;
            List<string> emailTitle = new List<string>();
            List<string> emailSubject = new List<string>();
            List<string> emailTo = new List<string>();
            List<string> emailCc = new List<string>();
            List<string> emailBcc = new List<string>();
            foreach (ResetWinningMailElement element in mailCollection)
            {
                emailTitle.Add(element.MailTitle);
                emailSubject.Add(element.MailSubject);
                emailTo.Add(element.MailTo);
                emailCc.Add(element.MailCc);
                emailBcc.Add(element.MailBcc);
            }

            try
            {
                var root = AppDomain.CurrentDomain.BaseDirectory;
                string filePath = root + EmailTemplateConstants.ResetWinningNotificationTemplate;
                string template = File.ReadAllText(filePath);
                var emailContent = Razor.Parse(template, status);
                string subject = string.Format(string.Join(",", emailSubject), criteria.FromDate);

                var mailItem = new Fanex.MailDeliver.Model.MailRecord
                {
                    MailTo = string.Join(",", emailTo),
                    Subject = subject,
                    Title = string.Join(",", emailTitle),
                    Body = emailContent
                };

                if (!string.IsNullOrEmpty(mailItem.MailTo.Trim()))
                {
                    using (var client = new Fanex.MailDeliver.MailClient.API.MailDeliver())
                    {
                        client.SendMail(mailItem);
                    }
                }
            }
            catch (Exception ex)
            {
                LogExtensions.ExceptionHandler(ex);
                isSuccess = false;
            }

            return isSuccess;
        }

